const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions: Mount Isa and Townsville, Queensland
  const mountIsa = ee.Geometry.Point([139.4917, -20.7267]); // Mount Isa
  const townsville = ee.Geometry.Point([146.7781, -19.2643]); // Townsville

  // Date range: January 27 to February 10, 2019
  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  // Load CHIRPS daily rainfall data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const size = chirps.size().getInfo();
  console.log(`CHIRPS images available: ${size}`);

  if (size === 0) {
    console.log("No CHIRPS data found for the date range.");
    console.log("C1");
    return;
  }

  // Sum precipitation over the period
  const totalPrecip = chirps.sum();

  // Check Mount Isa
  const mountIsaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mountIsaValue = mountIsaStats.precipitation;
  console.log(`Mount Isa total rainfall (mm): ${mountIsaValue !== null ? mountIsaValue.toFixed(2) : 'NaN'}`);

  // Check Townsville
  const townsvilleStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const townsvilleValue = townsvilleStats.precipitation;
  console.log(`Townsville total rainfall (mm): ${townsvilleValue !== null ? townsvilleValue.toFixed(2) : 'NaN'}`);

  // Validation
  if (mountIsaValue === null || townsvilleValue === null || 
      isNaN(mountIsaValue) || isNaN(townsvilleValue)) {
    console.log("Invalid/null rainfall values.");
    console.log("C3");
    return;
  }

  const threshold = 450; // 45 cm = 450 mm
  const mountIsaMet = mountIsaValue >= threshold;
  const townsvilleMet = townsvilleValue >= threshold;

  console.log(`Mount Isa >= 450mm: ${mountIsaMet}`);
  console.log(`Townsville >= 450mm: ${townsvilleMet}`);

  // Both regions must meet the threshold
  if (mountIsaMet && townsvilleMet) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
